class Solution {
public:
    vector<vector<int>> kSmallestPairs(vector<int>& nums1, vector<int>& nums2, int k) {
        vector<vector<int>> res;
        if (nums1.empty() || nums2.empty() || k <= 0) return res;
        auto cmp = [&](const tuple<int, int, int>& a, const tuple<int, int, int>& b) {
            return get<0>(a) > get<0>(b);
        };
        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, decltype(cmp)> pq(cmp);
        int n1 = min(k, (int)nums1.size());
        for (int i = 0; i < n1; ++i) {
            pq.push({nums1[i] + nums2[0], i, 0});
        }
        while (!pq.empty() && (int)res.size() < k) {
            auto [sum, i, j] = pq.top();
            pq.pop();
            res.push_back({nums1[i], nums2[j]});
            if (j + 1 < (int)nums2.size()) {
                pq.push({nums1[i] + nums2[j + 1], i, j + 1});
            }
        }
        return res;
    }
};

class Solution {
    public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
        List<List<Integer>> res = new ArrayList<>();
        if (nums1.length == 0 || nums2.length == 0 || k <= 0) return res;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        int n1 = Math.min(k, nums1.length);
        for (int i = 0; i < n1; i++) {
            pq.offer(new int[]{nums1[i] + nums2[0], i, 0});
        }
        while (!pq.isEmpty() && res.size() < k) {
            int[] top = pq.poll();
            int i = top[1], j = top[2];
            res.add(Arrays.asList(nums1[i], nums2[j]));
            if (j + 1 < nums2.length) {
                pq.offer(new int[]{nums1[i] + nums2[j + 1], i, j + 1});
            }
        }
        return res;
    }
}

/**
 * @param {number[]} nums1
 * @param {number[]} nums2
 * @param {number} k
 * @return {number[][]}
 */
var kSmallestPairs = function(nums1, nums2, k) {
    const res = [];
    if (!nums1.length || !nums2.length || k <= 0) return res;
    // Simple binary min-heap
    const heap = [];
    const push = (val) => {
        heap.push(val);
        let cur = heap.length - 1;
        while (cur > 0) {
            const parent = (cur - 1) >> 1;
            if (heap[cur][0] < heap[parent][0]) {
                [heap[cur], heap[parent]] = [heap[parent], heap[cur]];
                cur = parent;
            } else break;
        }
    };
    const pop = () => {
        const top = heap[0];
        const bottom = heap.pop();
        if (heap.length > 0) {
            heap[0] = bottom;
            let cur = 0;
            while ((cur << 1) + 1 < heap.length) {
                let left = (cur << 1) + 1;
                let right = left + 1;
                let best = (right < heap.length && heap[right][0] < heap[left][0]) ? right : left;
                if (heap[best][0] < heap[cur][0]) {
                    [heap[cur], heap[best]] = [heap[best], heap[cur]];
                    cur = best;
                } else break;
            }
        }
        return top;
    };

    const n1 = Math.min(k, nums1.length);
    for (let i = 0; i < n1; i++) {
        push([nums1[i] + nums2[0], i, 0]);
    }
    while (heap.length > 0 && res.length < k) {
        const [, i, j] = pop();
        res.push([nums1[i], nums2[j]]);
        if (j + 1 < nums2.length) {
            push([nums1[i] + nums2[j + 1], i, j + 1]);
        }
    }
    return res;
};
